#pragma once

static const char kStatusPage[] = R"rawliteral(<!DOCTYPE html>
<html><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>ScapeSense</title>
<style>
:root{color-scheme:dark}*{box-sizing:border-box}body{font:15px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#000;color:#ddd;margin:0}.panel{max-width:760px;margin:auto;padding:8px;border:1px solid #292929;border-radius:0 0 9px 9px}header{display:flex;align-items:center;justify-content:space-between;padding:7px 0 22px;font-weight:600}.connected{font-size:13px;font-weight:400;color:#00d45a;background:#002d12;border-radius:14px;padding:3px 7px}.connected.off{color:#ff6262;background:#310000}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:16px;padding:5px 12px 28px}.label,.unit,.muted{color:#bbb}.value{font-size:22px;font-weight:500;color:#f2f2f2;margin:6px 0}.value.bad{color:#ff6262}.meta{display:flex;justify-content:space-between;padding:0 0 24px}.gauge{height:18px;background:#1b1b1b;border:1px solid #303030;border-radius:10px;overflow:hidden;margin:14px 0 7px}.gauge-fill{height:100%;width:0;background:#00c853;transition:width .25s}.gauge-fill.warn{background:#f0a52d}.gauge-fill.low{background:#e53935}.gauge-label{display:flex;justify-content:space-between;font-size:13px;color:#aaa;margin-bottom:18px}.rule{border-top:1px solid #191919}.action{display:flex;justify-content:space-between;align-items:center;padding:23px 0 10px}.action h2,details h2{font-size:16px;margin:0 0 7px}.action p{margin:0;color:#aaa}.button{font:inherit;color:#ff5656;background:transparent;border:1px solid #8f1717;border-radius:18px;padding:7px 15px;cursor:pointer;text-decoration:none}.button:hover{background:#260707}.button.primary,.button.update{color:#7cb8ff;border-color:#17558f}.button.secondary{color:#ccc;border-color:#555}#notice{min-height:20px;padding-top:8px;color:#00d45a}details{padding:22px 0 10px}summary{cursor:pointer;font-weight:600;font-size:16px}.diag{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:18px 0}.diag div,.field{background:#111;border:1px solid #252525;border-radius:7px;padding:9px}.diag b{display:block;font-size:18px;margin-top:5px}.form{display:grid;grid-template-columns:1fr 1fr;gap:9px}.field-label{display:flex;align-items:center;gap:6px;color:#bbb;margin-bottom:6px}.info{position:relative;display:inline-grid;place-items:center;width:17px;height:17px;padding:0;border:1px solid #666;border-radius:50%;background:transparent;color:#bbb;font:600 11px serif;cursor:help}.info:after{content:attr(data-help);position:absolute;z-index:5;left:22px;top:-8px;width:230px;padding:9px;border:1px solid #444;border-radius:6px;background:#181818;color:#eee;font:13px/1.35 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;box-shadow:0 5px 18px #000;opacity:0;visibility:hidden;pointer-events:none}.info:hover:after,.info:focus:after{opacity:1;visibility:visible}.field input,.field select{width:100%;font:inherit;background:#050505;color:#eee;border:1px solid #444;border-radius:5px;padding:8px}.controls{display:flex;justify-content:flex-end;gap:8px;margin-top:12px;flex-wrap:wrap}canvas{width:100%;height:130px;background:#080808;border:1px solid #252525;border-radius:7px}.legend{display:flex;gap:14px;flex-wrap:wrap;margin:7px 2px 16px;color:#999;font-size:12px}.legend span:before{content:"";display:inline-block;width:18px;margin-right:5px;vertical-align:middle;border-top:2px solid}.legend .smoothed:before{border-color:#42a5ff}.legend .raw-trace:before{border-color:rgba(66,165,255,.4)}.legend .baseline-trace:before{border-color:#777}.legend .threshold-trace:before{border-color:#d49a3a;border-top-style:dashed}.daily-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:14px 0}.daily-summary div{background:#111;border:1px solid #252525;border-radius:7px;padding:9px}.daily-summary b{display:block;margin-top:5px;font-size:17px}.history-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;margin-top:12px}th,td{text-align:left;padding:8px;border-bottom:1px solid #222;white-space:nowrap}th{color:#999;font-weight:500}small{color:#888}@media(max-width:520px){.metrics{gap:15px;padding-left:0;padding-right:0}.meta{display:block}.meta span{display:block;margin-top:6px}.action{align-items:flex-start;gap:15px}.form{grid-template-columns:1fr}.diag{grid-template-columns:1fr 1fr}}
</style></head><body><main class="panel">
<header><span>ScapeSense</span><span id="connection" class="connected off">Disconnected</span></header>
<section class="metrics"><div><div class="label">Bubble rate</div><div id="bps" class="value">--</div><div class="unit">bubbles/sec</div></div><div><div class="label">Today's bubbles</div><div id="total" class="value">--</div><div class="unit">resets at UK midnight</div></div><div><div class="label">Water temperature</div><div id="temperature" class="value">--</div><div class="unit">celsius</div></div><div><div class="label">Cylinder weight</div><div id="weight" class="value">--</div><div id="weightUnit" class="unit">grams</div></div></section>
<div class="meta"><span>OLED: <b id="oled">--</b></span><span>Firmware: <b id="firmware">--</b></span></div>
<div class="rule"></div>
<details open><summary>Daily history</summary><div class="daily-summary"><div>Flow started<b id="todayStart">--</b></div><div>Flow stopped<b id="todayStop">--</b></div><div>Status<b id="flowStatus">--</b></div></div><div class="history-wrap"><table><thead><tr><th>Date</th><th>Bubbles</th><th>Started</th><th>Stopped</th></tr></thead><tbody id="historyRows"><tr><td colspan="4">No completed days yet</td></tr></tbody></table></div></details>
<div class="rule"></div>
<details><summary>Cylinder weighing</summary><div class="gauge"><div id="gasGauge" class="gauge-fill"></div></div><div class="gauge-label"><span>Estimated CO2 remaining</span><b id="gasPercent">--</b></div><div class="diag"><div>Raw counts <button type="button" class="info" aria-label="Raw load-cell counts help" data-help="The unscaled HX711 value. It changes with load and is used for calibration.">i</button><b id="loadCellRaw">--</b></div><div>Status <button type="button" class="info" aria-label="Load-cell status help" data-help="Shows whether the load cell is producing readings and whether calibration is complete.">i</button><b id="loadCellStatus">--</b></div><div>Calibration <button type="button" class="info" aria-label="Calibration help" data-help="Tare with no load, then place a known mass and enter its weight in grams.">i</button><b id="loadCellCalibrated">--</b></div></div><div class="form"><div class="field"><div class="field-label"><label for="emptyCylinder">Empty cylinder weight</label><button type="button" class="info" aria-label="Empty cylinder help" data-help="The total scale reading when the cylinder is empty, including any bracket or stand that stays on the scale.">i</button></div><input id="emptyCylinder" name="emptyCylinderG" type="number" min="0.1" max="100000" step="0.1"><small>Gross empty weight in grams</small></div><div class="field"><div class="field-label"><label for="co2Capacity">CO2 capacity</label><button type="button" class="info" aria-label="CO2 capacity help" data-help="The mass of CO2 the cylinder can hold when full. For a 2 kg cylinder this is normally 2000 g.">i</button></div><input id="co2Capacity" name="co2CapacityG" type="number" min="0.1" max="100000" step="0.1"><small>Gas capacity in grams</small></div><div class="field"><div class="field-label"><label for="knownMass">Known mass</label><button type="button" class="info" aria-label="Known mass help" data-help="After taring, place a known weight on the scale, enter its mass in grams, then calibrate. A full or empty CO2 cylinder can be used if its exact weight is known.">i</button></div><input id="knownMass" name="knownMassG" type="number" min="0.1" max="100000" step="0.1"><small>0.1-100000 g</small></div></div><div class="controls"><button id="useCurrentWeight" class="button secondary">Use current weight</button><button id="saveCylinder" class="button primary">Save cylinder settings</button><button id="tare" class="button secondary">Tare zero</button><button id="calibrate" class="button primary">Calibrate mass</button></div></details>
<div class="rule"></div>
<details><summary>Sensor tuning</summary><div class="diag"><div>Raw ADC <button type="button" class="info" aria-label="Raw ADC help" data-help="The latest light-sensor reading. Bubble detection uses this unsmoothed value.">i</button><b id="raw">--</b></div><div>Baseline <button type="button" class="info" aria-label="Baseline help" data-help="The slowly adapting normal sensor level when no bubble is passing.">i</button><b id="baseline">--</b></div><div>Difference <button type="button" class="info" aria-label="Difference help" data-help="The current movement away from baseline in the selected detection direction.">i</button><b id="difference">--</b></div></div><canvas id="graph" width="720" height="130" aria-label="Sensor readings graph"></canvas><div class="legend"><span class="smoothed">Smoothed signal</span><span class="raw-trace">Raw signal</span><span class="baseline-trace">Baseline</span><span class="threshold-trace">Detection threshold</span></div><div class="form">
<div class="field"><div class="field-label"><label for="threshold">Detection threshold</label><button type="button" class="info" aria-label="Detection threshold help" data-help="How far the sensor reading must move from its baseline before a bubble starts. Lower values are more sensitive but may count noise.">i</button></div><input id="threshold" name="threshold" type="number" min="10" max="1000"><small>10-1000 ADC; lower is more sensitive</small></div>
<div class="field"><div class="field-label"><label for="hysteresis">Hysteresis</label><button type="button" class="info" aria-label="Hysteresis help" data-help="How close the signal must return toward baseline before the current bubble ends. This prevents noise from counting one bubble more than once.">i</button></div><input id="hysteresis" name="hysteresis" type="number" min="5" max="500"><small>5-500 ADC; must be below threshold</small></div>
<div class="field"><div class="field-label"><label for="separation">Minimum separation</label><button type="button" class="info" aria-label="Minimum separation help" data-help="The shortest allowed time between counted bubbles. Raise it to suppress double counts; lower it to detect faster bubble streams.">i</button></div><input id="separation" name="minSeparationMs" type="number" min="20" max="1000"><small>20-1000 ms between bubbles</small></div>
<div class="field"><div class="field-label"><label for="reliable">Reliable rate ceiling</label><button type="button" class="info" aria-label="Reliable rate help" data-help="Rates above this limit are marked unreliable. It does not stop counting or control the CO2 supply.">i</button></div><input id="reliable" name="maxReliableBps" type="number" min="1" max="20"><small>1-20 bubbles/sec; warning limit only</small></div>
<div class="field"><div class="field-label"><label for="polarity">Detection polarity</label><button type="button" class="info" aria-label="Detection polarity help" data-help="Choose Signal falls when a bubble lowers the ADC reading, or Signal rises when a bubble raises it. The live graph helps identify the correct direction.">i</button></div><select id="polarity" name="polarity"><option value="0">Signal falls</option><option value="1">Signal rises</option></select><small>Direction of the bubble signal</small></div>
</div><div class="controls"><button id="defaults" class="button secondary">Restore defaults</button><button id="apply" class="button secondary">Apply temporarily</button><button id="save" class="button primary">Save settings</button></div></details>
<div class="rule"></div>
<section class="action"><div><h2>Reset bubble counts</h2><p>Clears the running total and rate history.</p></div><button id="reset" class="button">Reset</button></section>
<section class="action"><div><h2>Firmware update</h2><p>Upload firmware without changing saved settings.</p></div><a class="button update" href="/update">Update</a></section>
<div id="notice"></div>
</main><script>
const $=id=>document.getElementById(id),samples=[],emaAlpha=.2;let polarity=0,currentThreshold=150,smoothed=null,latestWeightG=null;
function massParts(g){return g>=1000?[(g/1000).toFixed(2),'kg']:g<10?[g.toFixed(1),'grams']:[Math.round(g).toString(),'grams']}
function draw(){const c=$('graph'),g=c.getContext('2d');g.clearRect(0,0,c.width,c.height);if(samples.length<2)return;const thresholdLine=s=>s.base+(polarity?currentThreshold:-currentThreshold),values=samples.flatMap(s=>[s.raw,s.smooth,s.base,thresholdLine(s)]),lo=Math.min(...values),hi=Math.max(...values,lo+1),y=v=>c.height-5-(v-lo)/(hi-lo)*(c.height-10),trace=(color,width,dash,value)=>{g.strokeStyle=color;g.lineWidth=width;g.setLineDash(dash);g.beginPath();samples.forEach((s,i)=>{const x=i*c.width/(samples.length-1);i?g.lineTo(x,y(value(s))):g.moveTo(x,y(value(s)))});g.stroke()};trace('rgba(66,165,255,.25)',1,[],s=>s.raw);trace('#777',1,[],s=>s.base);trace('#d49a3a',2,[7,5],thresholdLine);trace('#42a5ff',2,[],s=>s.smooth);g.setLineDash([])}
function show(d){$('bps').textContent=d.bps.toFixed(2);$('bps').classList.toggle('bad',!d.reliable);$('total').textContent=d.total.toLocaleString();$('oled').textContent=d.displayAwake?'awake':'sleeping';$('temperature').textContent=d.temperatureValid?d.temperatureC.toFixed(1):'--';const weightParts=d.weightValid&&d.loadCellCalibrated?massParts(d.weightG):['--','grams'];$('weight').textContent=weightParts[0];$('weightUnit').textContent=weightParts[1];$('loadCellRaw').textContent=d.loadCellRaw;$('loadCellStatus').textContent=d.loadCellBusy?'Calibrating':d.weightValid?'Ready':'No readings';$('loadCellCalibrated').textContent=d.loadCellCalibrated?'Calibrated':'Not calibrated';latestWeightG=d.weightValid&&d.loadCellCalibrated?d.weightG:null;if(!$('emptyCylinder').matches(':focus'))$('emptyCylinder').value=d.emptyCylinderG||'';if(!$('co2Capacity').matches(':focus'))$('co2Capacity').value=d.co2CapacityG||'';if(d.gasConfigured){const percent=Math.max(0,Math.min(100,d.gasRemainingPercent));$('gasGauge').style.width=percent+'%';$('gasGauge').className='gauge-fill'+(percent<15?' low':percent<35?' warn':'');const remainingParts=massParts(d.gasRemainingG);$('gasPercent').textContent=percent.toFixed(0)+'% ('+remainingParts[0]+' '+remainingParts[1]+')'}else{$('gasGauge').style.width='0';$('gasPercent').textContent='--'}$('firmware').textContent=d.firmware||'unknown';$('raw').textContent=d.raw;$('baseline').textContent=d.baseline;$('difference').textContent=polarity?(d.raw-d.baseline):(d.baseline-d.raw);smoothed=smoothed===null?d.raw:emaAlpha*d.raw+(1-emaAlpha)*smoothed;samples.push({raw:d.raw,smooth:smoothed,base:d.baseline});if(samples.length>150)samples.shift();draw()}
function connect(){const protocol=location.protocol==='https:'?'wss://':'ws://',ws=new WebSocket(protocol+location.host+'/ws');ws.onopen=()=>{$('connection').textContent='Connected';$('connection').classList.remove('off')};ws.onmessage=e=>show(JSON.parse(e.data));ws.onclose=()=>{$('connection').textContent='Disconnected';$('connection').classList.add('off');setTimeout(connect,1500)}}
function setForm(c){$('threshold').value=c.threshold;$('hysteresis').value=c.hysteresis;$('separation').value=c.minSeparationMs;$('reliable').value=c.maxReliableBps;$('polarity').value=c.polarity;currentThreshold=Number(c.threshold);polarity=Number(c.polarity)}
async function loadConfig(){const response=await fetch('/api/config');setForm(await response.json())}
const londonTime=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',hour:'2-digit',minute:'2-digit'});
function formatTime(epoch){return epoch?londonTime.format(new Date(epoch*1000)):'--'}
function formatDay(day){const value=String(day);return value.length===8?value.slice(6,8)+'/'+value.slice(4,6)+'/'+value.slice(0,4):'--'}
async function loadDailyStats(){const response=await fetch('/api/daily-stats');if(!response.ok)return;const data=await response.json(),current=data.current;$('todayStart').textContent=formatTime(current.start);$('todayStop').textContent=current.active?'--':formatTime(current.stop);$('flowStatus').textContent=current.active?'Active':current.start?'Stopped':'Not started';const rows=[...data.history].reverse();$('historyRows').innerHTML=rows.length?rows.map(day=>'<tr><td>'+formatDay(day.day)+'</td><td>'+day.count.toLocaleString()+'</td><td>'+formatTime(day.start)+'</td><td>'+formatTime(day.stop)+'</td></tr>').join(''):'<tr><td colspan="4">No completed days yet</td></tr>'}
function formData(){return new URLSearchParams({threshold:$('threshold').value,hysteresis:$('hysteresis').value,minSeparationMs:$('separation').value,maxReliableBps:$('reliable').value,polarity:$('polarity').value})}
async function tune(path,message){try{const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:formData()});const result=await response.json();if(!response.ok)throw new Error(result.error||'Request failed');currentThreshold=Number($('threshold').value);polarity=Number($('polarity').value);$('notice').textContent=message}catch(e){$('notice').textContent=e.message}setTimeout(()=>$('notice').textContent='',4000)}
$('apply').onclick=()=>tune('/api/config/apply','Temporary settings applied.');$('save').onclick=()=>confirm('Save these sensor settings?')&&tune('/api/config/save','Sensor settings saved.');$('defaults').onclick=async()=>{if(!confirm('Restore default sensor settings temporarily?'))return;const response=await fetch('/api/config/defaults',{method:'POST'});if(response.ok){setTimeout(loadConfig,300);$('notice').textContent='Default settings applied.'}};
$('useCurrentWeight').onclick=()=>{if(latestWeightG===null){$('notice').textContent='No valid weight reading.';return}$('emptyCylinder').value=latestWeightG.toFixed(1)};
$('saveCylinder').onclick=async()=>{const empty=Number($('emptyCylinder').value),capacity=Number($('co2Capacity').value);if(!(empty>0&&empty<=100000&&capacity>0&&capacity<=100000)||!confirm('Save empty cylinder weight and CO2 capacity?'))return;try{const response=await fetch('/api/cylinder/config',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({emptyCylinderG:empty,co2CapacityG:capacity})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Save failed');$('notice').textContent='Cylinder settings saved.'}catch(e){$('notice').textContent=e.message}setTimeout(()=>$('notice').textContent='',4000)};
$('tare').onclick=async()=>{if(!confirm('Tare the current load-cell reading as zero?'))return;try{const response=await fetch('/api/load-cell/tare',{method:'POST'});const result=await response.json();if(!response.ok)throw new Error(result.error||'Tare failed');$('notice').textContent='Tare request accepted.'}catch(e){$('notice').textContent=e.message}setTimeout(()=>$('notice').textContent='',4000)};
$('calibrate').onclick=async()=>{const mass=Number($('knownMass').value);if(!(mass>=0.1&&mass<=100000)||!confirm('Calibrate using '+mass+' g as the known mass?'))return;try{const response=await fetch('/api/load-cell/calibrate',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({knownMassG:mass})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Calibration failed');$('notice').textContent='Calibration request accepted.'}catch(e){$('notice').textContent=e.message}setTimeout(()=>$('notice').textContent='',4000)};
$('reset').onclick=async()=>{if(!confirm('Reset today\'s bubble count, activity times and rate history?'))return;$('reset').disabled=true;try{const response=await fetch('/api/reset-counts',{method:'POST'});if(!response.ok)throw new Error();$('notice').textContent='Today\'s bubble statistics reset.';setTimeout(loadDailyStats,300)}catch(e){$('notice').textContent='Reset failed.'}finally{$('reset').disabled=false;setTimeout(()=>$('notice').textContent='',3000)}};
loadConfig();loadDailyStats();setInterval(loadDailyStats,60000);connect();
</script></body></html>)rawliteral";
